#!/usr/bin/env python3
"""One exact no-output Tau probe after the original owner/artifact inventory."""
from pathlib import Path
from types import ModuleType
import base64, hashlib, json, os, subprocess, sys, time
sys.dont_write_bytecode = True
ROOT=Path('/workspace/p1-complete-proof/20261127-p15-tau-mathlib-probe-v1')
SHA='bb3e9be4179da59d60bae5698ce53ac4995084a29d557ed4679dbd72bc7409f3'
OLD_SHA='8e315aec5a3f00506ac26e8710474c47a448b043d3cf38be27c4df30c18a478f'
PAYLOAD=''
INVENTORY=Path('/workspace/p1-complete-proof/p15-staged-scripts/inventory_tau_readiness_7c2b06a3.py')
raw_inventory=INVENTORY.read_bytes()
assert hashlib.sha256(raw_inventory).hexdigest()=='7c2b06a3611e14c6e0757af113d540257c6c38a7359bbc48e385c4fe306c2380'
api=ModuleType('readonly_tau_inventory'); api.__file__=str(INVENTORY)
exec(compile(raw_inventory,str(INVENTORY),'exec'),api.__dict__)
preflight=api.inventory()
assert preflight['owner_history']==[], 'Prior owner requires reuse/inspection'
assert all(row['kind']=='absent' for row in preflight['target_project_inventory']['artifacts'].values()), 'Prior target artifacts require inspection'
assert all(row['matches'] for row in preflight['original_runtime'].values()), 'Original runtime differs'
assert preflight['original_owner_root']['kind']=='directory', 'Original owner root unavailable'
state_source=preflight['target_project_inventory']['source']
assert state_source['observed']['kind']=='absent' or state_source['matches'], 'Unexpected installed source'
raw=base64.b64decode(PAYLOAD)
assert len(raw)==11120 and hashlib.sha256(raw).hexdigest()==SHA
run=ROOT/SHA/'runs'/'attempt-00000'
assert run.resolve()==run and not os.path.lexists(run), 'Existing attempt must be preserved'
run.mkdir(parents=True,exist_ok=False)
source=run/'Part3ElementaryTauTruncation.lean'
with source.open('xb') as f:f.write(raw)
with (run/'PRECOMPILE_INVENTORY.json').open('x') as f:json.dump(preflight,f,indent=2,sort_keys=True);f.write('\n')
state='/workspace/blue-build-tools/member-runtime-evidence/state.json'
argv=['python3','/workspace/blue-build-tools/serialize_validation_lane.py','--state',state,
      '--receipt',str(run/'PROBE_LANE.json'),'python3','/workspace/blue-build-tools/run_guarded.py',
      '--state',state,'lake','--no-build','env','lean',str(source)]
log=run/'probe.log';start=time.time()
result={'schema':'p15_tau_truncation_mathlib_only_probe_v1','source_commit_base':'040d46058821746c69c5183b3f6c22792287c4ba',
        'source_sha256':SHA,'source_bytes':len(raw),'original_source_sha256':OLD_SHA,
        'proof_body_unchanged':True,'project_dependencies':[],'imports':['Mathlib'],
        'argv':argv,'cwd':'/workspace/blue-member-build','output_object_requested':False,
        'new_owner_accepted':False,'whole_P1_5_complete':False,'native_stock_executed':False}
with log.open('xb') as f:
    p=subprocess.run(argv,cwd='/workspace/blue-member-build',stdout=f,stderr=subprocess.STDOUT)
result.update(exit_code=p.returncode,elapsed_seconds=time.time()-start,probe_passed=p.returncode==0,
              log_path=str(log),log_bytes=log.stat().st_size,log_sha256=hashlib.sha256(log.read_bytes()).hexdigest())
with (run/'PROBE_RESULT.json').open('x') as f:json.dump(result,f,indent=2,sort_keys=True);f.write('\n')
print(json.dumps(result,sort_keys=True),flush=True)
print(log.read_text(errors='replace')[-20000:],flush=True)
raise SystemExit(p.returncode)
